	ok := RegisterRequest{ItemID: "seat", VersionID: "v1", UnitPrice: 100, Start: at(0)}

	if err := b.RegisterVersion(RegisterRequest{VersionID: "v1", UnitPrice: 1, Start: at(0)}); !errors.Is(err, ErrEmptyItemID) {
		t.Fatalf("empty item: %v", err)
	}
