		t.Fatalf("empty version: %v", err)
	}
	r := ok
	r.UnitPrice = -1
	if err := b.RegisterVersion(r); !errors.Is(err, ErrInvalidUnitPrice) {
		t.Fatalf("negative price: %v", err)
	}
