	r.VersionID = "v2"
	r.Start = time.Time{}
	if err := b.RegisterVersion(r); !errors.Is(err, ErrStartRequired) {
		t.Fatalf("missing start: %v", err)
	}
	r = ok
	r.VersionID = "v2"
	r.End = atPtr(0) // 结束必须晚于开始
	if err := b.RegisterVersion(r); !errors.Is(err, ErrInvalidInterval) {
		t.Fatalf("end == start: %v", err)
	}
	r.End = atPtr(-1)
	if err := b.RegisterVersion(r); !errors.Is(err, ErrInvalidInterval) {
		t.Fatalf("end < start: %v", err)
